WITH gated AS (SELECT model FROM llm_gateway.usage_log WHERE {{ time_filter('timestamp') }} AND model != '' GROUP BY model HAVING count() >= 100) SELECT * FROM (SELECT concat(substring(term, 1, 1), '***', substring(term, length(term), 1)) AS "Rejection String", 'Profanity' AS "Category", count() AS "Occurrences" FROM (SELECT arrayJoin(profane_terms) AS term FROM llm_gateway.request_signals WHERE {{ time_filter('timestamp') }} AND model IN (SELECT model FROM gated)) GROUP BY term UNION ALL SELECT term AS "Rejection String", 'Frustration phrase' AS "Category", count() AS "Occurrences" FROM (SELECT arrayJoin(frustration_terms) AS term FROM llm_gateway.request_signals WHERE {{ time_filter('timestamp') }} AND model IN (SELECT model FROM gated)) GROUP BY term) ORDER BY "Occurrences" DESC LIMIT 15